import { useNavigate } from "react-router-dom";
import { Pie } from "react-chartjs-2";
import { Chart as ChartJS, ArcElement, Tooltip, Legend } from "chart.js";
import "./DashboardPage.css";

ChartJS.register(ArcElement, Tooltip, Legend);

function DashboardPage() {
  const navigate = useNavigate();

  // Dummy data (tum backend se bhi la sakti ho later)
  const data = {
    labels: ["Child", "Teenage", "Young", "Senior"],
    datasets: [
      {
        label: "Patients",
        data: [10, 20, 45, 25],
        backgroundColor: ["#4ade80", "#60a5fa", "#fbbf24", "#f87171"],
        borderWidth: 1,
      },
    ],
  };

  return (
    <div className="dashboard-container">

      {/* Header */}
      <div className="dashboard-header">
        <h1>Heart Health Analytics Dashboard</h1>

        <div className="btn-group">
          <button onClick={() => navigate("/predict")} className="btn-blue">
            Prediction
          </button>

          <button onClick={() => navigate("/")} className="btn-red">
            Logout
          </button>
        </div>
      </div>

      {/* Grid */}
      <div className="dashboard-grid">

        <div className="card">
          <h2>Heart Disease Causes</h2>
          <p>Smoking, High BP, Cholesterol, Stress, Obesity are major risk factors.</p>
        </div>

        <div className="card">
          <h2>Prevention Tips</h2>
          <p>Daily exercise, healthy diet, no smoking, regular health checkups.</p>
        </div>

        <div className="card">
          <h2>Total Patients Overview</h2>
          <h1>128</h1>
          <p>Currently analyzed records in system</p>
        </div>

        {/* PIE CHART */}
        <div className="card chart-card">
          <h2>Age Group Distribution</h2>
          <Pie data={data} />
        </div>

      </div>
    </div>
  );
}

export default DashboardPage;
